mapper.select:
SELECT T.* FROM (SELECT A.*, C.TESTNAME, B.METHODID, B.TESTID, B.ISLOCKED, B.TESTCLASS, D.METHODNAME, E.SETNAME, F.TESTCATEGORYDESC AS ITEMTESTCATEGORY, TM.TESTMETHODTYPE, TO_CHAR(CD.CODENAME) AS ANALYSISCATEGORYNAME FROM T_EMC_ITEM A LEFT JOIN T_EMC_TEST_METHOD B ON A.TESTMETHODID = B.ID LEFT JOIN T_EMC_TEST C ON B.TESTID = C.ID LEFT JOIN T_EMC_METHOD D ON B.METHODID = D.ID LEFT JOIN T_EMC_STANDARD_SET E ON A.STANDSETID = E.ID LEFT JOIN T_EMC_TEST_CATEGORY F ON B.TESTCATEGORYID = F.ID LEFT JOIN T_EMC_TEST_METHOD TM ON A.TESTMETHODID = TM.ID LEFT JOIN T_CORE_CODE CD ON A.analysisCategory = CD.CODE AND CD.CODECATEGORYID = 'analysisCategory') T
AND NOT EXISTS (SELECT 1 FROM ${targetTable} TAR_ WHERE TAR_.${targetItemIdColumn} = T.ID
AND TAR_.${targetFilterColumn} = #{targetFilterValue}
AND TAR_.${targetFilterColumn1} = #{targetFilterValue1}
)
AND EXISTS(SELECT 1 FROM T_EMC_MONITOR_SCHEME SCHEME, T_EMC_GROUP_ITEM GI WHERE SCHEME.ITEMGROUPID = GI.ITEMGROUPID AND GI.ITEMID = T.ID AND SCHEME.MONITORTMPLID = #{targetMonitorTmplId} AND SCHEME.TESTID = #{targetTestId} AND SCHEME.METHODID = #{targetMethodId})
AND EXISTS(SELECT 1 FROM T_EMC_EQUIPT_TEST_METHOD ETM WHERE ETM.TESTMETHODID = T.TESTMETHODID AND ETM.EQUIPTID = #{TESTMETHODIDFILTER})
AND EXISTS(SELECT 1 FROM T_EMC_TEST_CAPACITY M WHERE M.TESTMETHODID = T.TESTMETHODID AND M.ORGID = #{loginUser.ext$.parentorgid})
ORDER BY
T.TESTMETHODID DESC, T.ORDERNO
